tool_calls.arguments:
{"command":"kubectl get pods --all-namespaces -o jsonpath='{range .items[*]}{.metadata.namespace}{"\t"}{.metadata.name}{"\n"}{end}' | grep -v -e "kube-system" | xargs kubectl get pods -n 
    ; 
    kubectl get pods --all-namespaces -o jsonpath='{range .items[*]}{.metadata.namespace}{"\t"}{.metadata.name}{"\n"}{end}' | while read NS POD; do
        kubectl get pods -n $NS $POD;
    done | grep -E "CrashLoopBackOff|Pending|ImagePullBackOff""}

